CREATE TABLE IF NOT EXISTS hub_resources (owner TEXT NOT NULL, account_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, included INTEGER NOT NULL DEFAULT 1, shared INTEGER NOT NULL DEFAULT 0, manual INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY(owner,account_id,user_id));
CREATE TABLE IF NOT EXISTS hub_resource_scan (owner TEXT NOT NULL, account_id TEXT NOT NULL, scan_id TEXT NOT NULL, cursor TEXT, seen_cursors TEXT NOT NULL DEFAULT '[]', complete INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY(owner,account_id));
CREATE TABLE IF NOT EXISTS hub_resource_links (owner TEXT NOT NULL, account_id TEXT NOT NULL, user_id TEXT NOT NULL, task_id TEXT NOT NULL, payload TEXT NOT NULL, scan_id TEXT NOT NULL, PRIMARY KEY(owner,account_id,user_id,task_id));
CREATE TABLE IF NOT EXISTS hub_resource_days (owner TEXT NOT NULL, account_id TEXT NOT NULL, user_id TEXT NOT NULL, day TEXT NOT NULL, presence TEXT NOT NULL, target_minutes INTEGER, updated_at INTEGER NOT NULL, PRIMARY KEY(owner,account_id,user_id,day));
